import * as React from "react"
import { Link } from "gatsby"
import AppLinksFooter from "./AppLinksFooter"

const Layout = ({ location, title, children }) => {
  const rootPath = `${__PATH_PREFIX__}/`
  const isRootPath = location.pathname === rootPath
  let header

  if (isRootPath) {
    header = (
      <h1 className="main-heading">
        <Link to="/">{title}</Link>
      </h1>
    )
  } else {
    header = (
      <Link className="header-link-home" to="/">
        {title}
      </Link>
    )
  }

  return (
    <div className="global-wrapper" data-is-root-path={isRootPath}>
      <header className="global-header">{header}</header>
      <main>{children}</main>
      <AppLinksFooter />
      <footer>
        <p>
          <a rel="license" href="http://creativecommons.org/licenses/by-nc/4.0/">
            <img alt="クリエイティブ・コモンズ・ライセンス" style={{borderWidth:0}} src="https://i.creativecommons.org/l/by-nc/4.0/88x31.png" />
          </a>
          <br />
          この 作品 は <a rel="license" href="http://creativecommons.org/licenses/by-nc/4.0/">クリエイティブ・コモンズ 表示 - 非営利 4.0 国際 ライセンス</a>の下に提供されています。
        </p>
        © {new Date().getFullYear()}, Built with
        {` `}
        <a href="https://www.gatsbyjs.com">Gatsby</a>
      </footer>
    </div>
  )
}

export default Layout
